BEGIN;

CREATE TABLE IF NOT EXISTS "user_role_history" (
    "user_role_history_id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "target_user_id" NUMERIC(20, 0) NOT NULL
        REFERENCES "users" ("user_id") ON DELETE RESTRICT,
    "previous_role_code" VARCHAR(40) NOT NULL,
    "new_role_code" VARCHAR(40) NOT NULL
        CHECK ("new_role_code" IN ('CUSTOMER', 'SALES')),
    "actor_user_id" NUMERIC(20, 0) NOT NULL
        REFERENCES "users" ("user_id") ON DELETE RESTRICT,
    "actor_name" VARCHAR(160) NOT NULL,
    "actor_email" VARCHAR(200) NOT NULL,
    "actor_role_code" VARCHAR(40) NOT NULL CHECK ("actor_role_code" = 'ADMIN'),
    "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS "ix_user_role_history_target_date"
    ON "user_role_history" ("target_user_id", "created_at", "user_role_history_id");

COMMIT;
